+// Copied and modified from DeepEP
+__forceinline__ __device__ float fast_pow2(int x) {
+  // We can ensure `-126 <= x and x <= 127`
+  uint32_t bits_x = (x + 127) << 23;
+  return *reinterpret_cast<float*>(&bits_x);
+}
+
+// Copied and modified from DeepEP
+__forceinline__ __device__ int fast_log2_ceil(float x) {
+  auto bits_x = *reinterpret_cast<uint32_t*>(&x);
+  auto exp_x = (bits_x >> 23) & 0xff;
+  auto man_bits = bits_x & ((1 << 23) - 1);
+  return exp_x - 127 + (man_bits != 0);
+}
+
+// Copied and modified from DeepEP
+template <bool ROUND_SCALE, typename dtype_info>
+__forceinline__ __device__ void calculate_fp8_scales(float amax, float& scale,
+                                                     float& scale_inv) {
+  constexpr float MAX_8BIT_INV = 1.0f / dtype_info::MAX;
+  if constexpr (ROUND_SCALE) {
+    auto exp_scale_inv = fast_log2_ceil(amax * MAX_8BIT_INV);
+    scale = fast_pow2(-exp_scale_inv);
+    scale_inv = fast_pow2(exp_scale_inv);
+  } else {
+    scale_inv = amax * MAX_8BIT_INV;
+    scale = dtype_info::MAX / amax;
+  }
+}
+
+// Copied and modified from DeepEP
+template <bool SCALE_UE8M0, typename OUT_DTYPE_T =
+                                std::conditional_t<SCALE_UE8M0, uint8_t, float>>
+__forceinline__ __device__ OUT_DTYPE_T
+extract_required_scale_format(float value) {
+  if constexpr (SCALE_UE8M0) {
+    return static_cast<uint8_t>((*reinterpret_cast<uint32_t*>(&value)) >> 23);
+  } else {
+    return value;
+  }
+}
+
+__device__ __forceinline__ void st_global(const int4* ptr, const int4& value) {
+#ifndef USE_MUSA
+  asm volatile("st.global.v4.s32 [%0], {%1, %2, %3, %4};" ::"l"(ptr),
+               "r"(value.x), "r"(value.y), "r"(value.z), "r"(value.w));
+#else
+  int4* p = const_cast<int4*>(ptr);
+  *p = value;
+#endif
+}
+
+__device__ __forceinline__ int4 ld_global_nc(const int4* ptr) {
+#ifndef USE_MUSA
+  int4 ret;
+  asm volatile("ld.global.nc.v4.s32 {%0, %1, %2, %3}, [%4];"
+               : "=r"(ret.x), "=r"(ret.y), "=r"(ret.z), "=r"(ret.w)
+               : "l"(ptr));
+  return ret;
+#else
+  return *ptr;
+#endif
+}
+
+template <typename T>
+struct DtypeInfo;
+
+template <>
+struct DtypeInfo<int8_t> {
+  static constexpr float MIN = -128;
+  static constexpr float MAX = 127;
+};
+
+template <>
+struct DtypeInfo<c10::Float8_e4m3fn> {
+  static constexpr float MIN = -448;
+  static constexpr float MAX = 448;
+};
+
+template <bool FUSE_SILU_AND_MUL>
+__device__ __forceinline__ int64_t compute_input_group_start_offset(
+    int expert_idx, int token_idx, int hidden_dim_group_idx, int hidden_size,
+    int num_tokens_per_expert, int group_size) {
+  return static_cast<int64_t>(expert_idx) * num_tokens_per_expert *
+             hidden_size * (FUSE_SILU_AND_MUL ? 2 : 1) +
+         static_cast<int64_t>(token_idx) * hidden_size *
+             (FUSE_SILU_AND_MUL ? 2 : 1) +
+         static_cast<int64_t>(hidden_dim_group_idx) * group_size;
+}
+
+constexpr float LOCAL_ABSMAX_ABS = 1e-10;
+constexpr uint32_t INPUT_PRIMARY_VEC_NUM_BYTES = 32;
+
+struct NaiveScheduler {
+  static void compute_exec_config(int threads_per_subwarp,
+                                  int num_local_experts,
+                                  int hidden_dim_num_groups, int64_t num_groups,
+                                  int num_tokens_per_expert,
+                                  int& subwarps_per_block, dim3& grid,
+                                  dim3& block) {
+    subwarps_per_block = ([=]() -> int {
+      if (num_groups % 16 == 0) {
+        return 16;
+      } else if (num_groups % 8 == 0) {
+        return 8;
+      } else if (num_groups % 4 == 0) {
+        return 4;
+      } else if (num_groups % 2 == 0) {
+        return 2;
+      }
+      return 1;
+    })();
+    grid = dim3(num_groups / subwarps_per_block);
+    block = dim3(subwarps_per_block * threads_per_subwarp);
+  }
+
+  template <bool FUSE_SILU_AND_MUL, int GROUP_SIZE, int THREADS_PER_SUBWARP,
+            typename FUNC>
+  __device__ __forceinline__ static void execute(
+      const int subwarps_per_block, const int hidden_dim_num_groups,
+      const int32_t* masked_m, const int num_tokens_per_expert, FUNC fn) {
+    constexpr int expert_idx = 0;
+
+    const int64_t subwarp_id = threadIdx.x / THREADS_PER_SUBWARP;
+    const int lane_id = threadIdx.x % THREADS_PER_SUBWARP;
+
+    const int64_t block_group_id = blockIdx.x * subwarps_per_block;
+    const int64_t group_id = block_group_id + subwarp_id;
+
+    int64_t input_group_start_offset;
+    if constexpr (!FUSE_SILU_AND_MUL) {
+      input_group_start_offset = group_id * GROUP_SIZE;
+    }
+
+    const int token_idx = group_id / hidden_dim_num_groups;
+    // At the hidden_size dimension, we are handling idx-th group
+    const int hidden_dim_group_idx = group_id % hidden_dim_num_groups;
+
+    if constexpr (FUSE_SILU_AND_MUL) {
+      const int hidden_size = hidden_dim_num_groups * GROUP_SIZE;
+      input_group_start_offset =
+          compute_input_group_start_offset<FUSE_SILU_AND_MUL>(
+              expert_idx, token_idx, hidden_dim_group_idx, hidden_size,
+              num_tokens_per_expert, GROUP_SIZE);
+    }
+
+    fn(expert_idx, token_idx, hidden_dim_group_idx, lane_id,
+       input_group_start_offset);
+  }
+};
+
+struct MaskedLayoutScheduler {
+  // Blocks grid-stride over tokens. A fixed 128 avoids launching mostly-empty
+  // blocks when masked_m is far below the padded capacity (decode).
+  static constexpr int DEFAULT_TOKEN_DIM_BLOCKS = 128;
+  static constexpr int SUBWARPS_PER_BLOCK = 16;
+
+  static void compute_exec_config(int threads_per_subwarp,
+                                  int num_local_experts,
+                                  int hidden_dim_num_groups, int64_t num_groups,
+                                  int num_tokens_per_expert,
+                                  int& subwarps_per_block, dim3& grid,
+                                  dim3& block) {
+    subwarps_per_block = SUBWARPS_PER_BLOCK;
+    STD_TORCH_CHECK(hidden_dim_num_groups % subwarps_per_block == 0);
+    const int token_dim_blocks =
+        std::min(DEFAULT_TOKEN_DIM_BLOCKS, num_tokens_per_expert);
+    grid = dim3(hidden_dim_num_groups / subwarps_per_block, token_dim_blocks,
+                num_local_experts);
+    block = dim3(subwarps_per_block * threads_per_subwarp);
+  }
+
+  template <bool FUSE_SILU_AND_MUL, int GROUP_SIZE, int THREADS_PER_SUBWARP,
+            typename FUNC>
+  __device__ __forceinline__ static void execute(
+      const int subwarps_per_block, const int hidden_dim_num_groups,
+      const int32_t* masked_m, const int num_tokens_per_expert, FUNC fn) {
+    const int64_t subwarp_id = threadIdx.x / THREADS_PER_SUBWARP;
+    const int lane_id = threadIdx.x % THREADS_PER_SUBWARP;
+
+    const int expert_idx = blockIdx.z;
+    const int token_idx_start = blockIdx.y;
+
+    const int64_t hidden_dim_group_idx =
+        blockIdx.x * SUBWARPS_PER_BLOCK + subwarp_id;
+
+    const int curr_expert_token_num = masked_m[expert_idx];
+
+    for (int token_idx = token_idx_start; token_idx < curr_expert_token_num;
+         token_idx += gridDim.y) {
+      const int hidden_size = hidden_dim_num_groups * GROUP_SIZE;
+      const int64_t input_group_start_offset =
+          compute_input_group_start_offset<FUSE_SILU_AND_MUL>(
+              expert_idx, token_idx, hidden_dim_group_idx, hidden_size,
+              num_tokens_per_expert, GROUP_SIZE);
+      fn(expert_idx, token_idx, hidden_dim_group_idx, lane_id,
+         input_group_start_offset);
+    }
+  }
+};
+
+template <
+    typename SCHEDULER, int GROUP_SIZE, int THREADS_PER_SUBWARP, typename T,
+    typename DST_DTYPE, bool IS_COLUMN_MAJOR = false, bool SCALE_UE8M0 = false,
+    bool FUSE_SILU_AND_MUL = false, bool ROUND_SCALE = SCALE_UE8M0,
+    typename scale_packed_t = std::conditional_t<SCALE_UE8M0, uint32_t, float>>
+__global__ void per_token_group_quant_8bit_kernel(
+    const T* __restrict__ input, DST_DTYPE* __restrict__ output_q,
+    scale_packed_t* __restrict__ output_s, const int32_t* __restrict__ masked_m,
+    const int subwarps_per_block, const int hidden_dim_num_groups,
+    // TODO can this be removed?
+    const int scale_expert_stride, const int scale_hidden_stride,
+    const int num_tokens_per_expert, const float max_8bit,
+    const float clamp_limit) {
+  using dst_dtype_info = DtypeInfo<DST_DTYPE>;
+  using scale_element_t = std::conditional_t<SCALE_UE8M0, uint8_t, float>;
+  static_assert(sizeof(scale_packed_t) % sizeof(scale_element_t) == 0);
+
+#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 900
+  cudaGridDependencySynchronize();
+#endif
+
+  SCHEDULER::execute<FUSE_SILU_AND_MUL, GROUP_SIZE, THREADS_PER_SUBWARP>(
+      subwarps_per_block, hidden_dim_num_groups, masked_m,
+      num_tokens_per_expert,
+      [&](const int expert_idx, const int token_idx,
+          const int hidden_dim_group_idx, const int lane_id,
+          const int64_t input_group_start_offset) {
+        constexpr uint32_t INPUT_PRIMARY_VEC_SIZE =
+            INPUT_PRIMARY_VEC_NUM_BYTES / sizeof(T);
+        constexpr uint32_t INPUT_PRIMARY_INT4_SIZE =
+            INPUT_PRIMARY_VEC_NUM_BYTES / sizeof(int4);
+
+        const int offset_num_groups =
+            expert_idx * num_tokens_per_expert * hidden_dim_num_groups +
+            token_idx * hidden_dim_num_groups + hidden_dim_group_idx;
+
+        int4 input_primary_int4[INPUT_PRIMARY_INT4_SIZE];
+        T* input_primary_vec = reinterpret_cast<T*>(input_primary_int4);
+        static_assert(sizeof(input_primary_vec[0]) * INPUT_PRIMARY_VEC_SIZE ==
+                      sizeof(input_primary_int4));
+
+        int4 input_secondary_int4[INPUT_PRIMARY_INT4_SIZE];
+        T* input_secondary_vec = reinterpret_cast<T*>(input_secondary_int4);
+        static_assert(sizeof(input_secondary_vec[0]) * INPUT_PRIMARY_VEC_SIZE ==
+                      sizeof(input_secondary_int4));
+
+#pragma unroll
+        for (uint32_t j = 0; j < INPUT_PRIMARY_INT4_SIZE; ++j) {
+          input_primary_int4[j] = ld_global_nc(
+              reinterpret_cast<const int4*>(input + input_group_start_offset +
+                                            lane_id * INPUT_PRIMARY_VEC_SIZE) +
+              j);
+        }
+        if constexpr (FUSE_SILU_AND_MUL) {
+          const int secondary_offset = hidden_dim_num_groups * GROUP_SIZE;
+#pragma unroll
+          for (uint32_t j = 0; j < INPUT_PRIMARY_INT4_SIZE; ++j) {
+            input_secondary_int4[j] = ld_global_nc(
+                reinterpret_cast<const int4*>(input + input_group_start_offset +
+                                              lane_id * INPUT_PRIMARY_VEC_SIZE +
+                                              secondary_offset) +
+                j);
+          }
+        }
+
+        constexpr int num_elems_per_pack =
+            static_cast<int>(sizeof(scale_packed_t) / sizeof(scale_element_t));
+        scale_element_t* scale_output;
+        if constexpr (IS_COLUMN_MAJOR) {
+          constexpr int scale_token_stride = 1;
+
+          const int hidden_idx_packed =
+              hidden_dim_group_idx / num_elems_per_pack;
+          const int pack_idx = hidden_dim_group_idx % num_elems_per_pack;
+          scale_output =
+              reinterpret_cast<scale_element_t*>(output_s) +
+              (expert_idx * scale_expert_stride * num_elems_per_pack +
+               hidden_idx_packed * scale_hidden_stride * num_elems_per_pack +
+               token_idx * scale_token_stride * num_elems_per_pack + pack_idx);
+        } else {
+          static_assert(!SCALE_UE8M0);
+          scale_output = output_s + offset_num_groups;
+        }
+
+        // can speed up if too slow
+        if constexpr (IS_COLUMN_MAJOR and SCALE_UE8M0) {
+          const int remainder_num_groups =
+              hidden_dim_num_groups % num_elems_per_pack;
+          if ((remainder_num_groups != 0) and
+              (hidden_dim_group_idx == hidden_dim_num_groups - 1) and
+              (lane_id < num_elems_per_pack - remainder_num_groups)) {
+            const int shift = 1 + lane_id;
+            *(scale_output + shift) = 0;
+          }
+        }
+
+        float local_absmax = LOCAL_ABSMAX_ABS;
+
+#pragma unroll
+        for (uint32_t j = 0; j < INPUT_PRIMARY_VEC_SIZE; ++j) {
+          float val;
+          if constexpr (FUSE_SILU_AND_MUL) {
+            float gate = static_cast<float>(input_primary_vec[j]);
+            float up = static_cast<float>(input_secondary_vec[j]);
+            if (clamp_limit > 0.0f) {
+              input_primary_vec[j] = static_cast<T>(fminf(gate, clamp_limit));
+              input_secondary_vec[j] =
+                  static_cast<T>(fminf(fmaxf(up, -clamp_limit), clamp_limit));
+              gate = static_cast<float>(input_primary_vec[j]);
+              up = static_cast<float>(input_secondary_vec[j]);
+            }
+            // Keep the same single visible low-precision boundary as the
+            // contiguous activation path.  Rounding SiLU before multiplying
+            // changes the second MoE GEMM's FP8 inputs.
+            T val_lowprec = static_cast<T>(silu(gate) * up);
+            val = static_cast<float>(val_lowprec);
+            input_primary_vec[j] = val_lowprec;
+          } else {
+            val = static_cast<float>(input_primary_vec[j]);
+          }
+
+          float abs_val = fabsf(val);
+          local_absmax = fmaxf(local_absmax, abs_val);
+        }
+
+        local_absmax =
+            GroupReduceMax<THREADS_PER_SUBWARP>(local_absmax, lane_id);
+
+        float y_scale, y_scale_inv;
+        if constexpr (ROUND_SCALE) {
+          calculate_fp8_scales<true, dst_dtype_info>(local_absmax, y_scale,
+                                                     y_scale_inv);
+        } else {
+          // Preserve the scale and division sequence of the legacy unmasked
+          // quantizer.  Reciprocal reuse under -use_fast_math moves a few
+          // values across an FP8 rounding boundary.
+          y_scale_inv = __fdiv_rn(local_absmax, max_8bit);
+          y_scale = 1.0f / y_scale_inv;
+        }
+
+        if (lane_id == 0) {
+          *scale_output =
+              extract_required_scale_format<SCALE_UE8M0>(y_scale_inv);
+        }
+
+        int4 output_buf;
+        static_assert(sizeof(output_buf) ==
+                      INPUT_PRIMARY_VEC_SIZE * sizeof(DST_DTYPE));
+
+        if constexpr (std::is_same_v<DST_DTYPE, c10::Float8_e4m3fn>) {
+          if constexpr (SCALE_UE8M0) {
+            const auto output_buf_ptr =
+                reinterpret_cast<__nv_fp8x2_storage_t*>(&output_buf);
+            static_assert(sizeof(output_buf) ==
+                          INPUT_PRIMARY_VEC_SIZE / 2 *
+                              sizeof(__nv_fp8x2_storage_t));
+            static_assert(INPUT_PRIMARY_VEC_SIZE % 2 == 0);
+
+#pragma unroll
+            for (uint32_t j = 0; j < INPUT_PRIMARY_VEC_SIZE; j += 2) {
+              float2 inputx2 = {static_cast<float>(input_primary_vec[j]),
+                                static_cast<float>(input_primary_vec[j + 1])};
+              float2 outputx2 = fmul2_rn(inputx2, {y_scale, y_scale});
+
+              outputx2.x = fminf(fmaxf(outputx2.x, dst_dtype_info::MIN),
+                                 dst_dtype_info::MAX);
+              outputx2.y = fminf(fmaxf(outputx2.y, dst_dtype_info::MIN),
+                                 dst_dtype_info::MAX);
+
+              output_buf_ptr[j / 2] =
+                  __nv_cvt_float2_to_fp8x2(outputx2, __NV_SATFINITE, __NV_E4M3);
+            }
+          } else {
+            // Match the legacy SM90 quantizer's scalar conversion exactly;
+            // packed conversion makes a different tie choice for rare values.
+            const auto output_buf_ptr =
+                reinterpret_cast<DST_DTYPE*>(&output_buf);
+#pragma unroll
+            for (uint32_t j = 0; j < INPUT_PRIMARY_VEC_SIZE; ++j) {
+              float val = static_cast<float>(input_primary_vec[j]);
+              float q_val =
+                  fminf(fmaxf(__fdiv_rn(val, y_scale_inv), dst_dtype_info::MIN),
+                        dst_dtype_info::MAX);
+              output_buf_ptr[j] = DST_DTYPE(q_val);
+            }
+          }
+        } else {
+          const auto output_buf_ptr = reinterpret_cast<DST_DTYPE*>(&output_buf);
+
+#pragma unroll
+          for (uint32_t j = 0; j < INPUT_PRIMARY_VEC_SIZE; ++j) {
+            float val = static_cast<float>(input_primary_vec[j]);
+            float q_val = fminf(fmaxf(val * y_scale, dst_dtype_info::MIN),
+                                dst_dtype_info::MAX);
+            output_buf_ptr[j] = DST_DTYPE(q_val);
+          }
+        }
+
+        st_global(reinterpret_cast<int4*>(
+                      output_q +
+                      static_cast<int64_t>(offset_num_groups) * GROUP_SIZE +
+                      lane_id * INPUT_PRIMARY_VEC_SIZE),
+                  output_buf);
+      });
+
+#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 900
+  cudaTriggerProgrammaticLaunchCompletion();
+#endif
+}
+
+void fused_silu_mul_per_token_group_quant(
+    // vanilla: (num_tokens, hidden_size)
+    // fuse_silu_and_mul: (num_tokens, hidden_size * 2)
+    // fuse_silu_and_mul + masked_layout: (num_experts, num_tokens-with-padding,
+    // hidden_size * 2)
+    const torch::stable::Tensor& input, torch::stable::Tensor& output_q,
+    torch::stable::Tensor& output_s, int64_t group_size, double eps,
+    double min_8bit, double max_8bit, double clamp_limit, bool round_scale,
+    bool scale_ue8m0, bool fuse_silu_and_mul,
+    const std::optional<torch::stable::Tensor>& masked_m) {
+  CHECK_INPUT(input);
+  CHECK_INPUT(output_q);
+  STD_TORCH_CHECK(input.numel() > 0);
+
+  STD_TORCH_CHECK(std::abs(LOCAL_ABSMAX_ABS - eps) < 1e-13);
+
+  CHECK_EQ(input.numel() % group_size, 0);
+  const int64_t num_groups =
+      input.numel() / group_size / (fuse_silu_and_mul ? 2 : 1);
+
+  const bool masked_layout = masked_m.has_value();
+  STD_TORCH_CHECK(output_s.dim() == (masked_layout ? 3 : 2));
+
+  const int num_local_experts = masked_layout ? input.size(0) : 1;
+
+  cudaStream_t stream = get_current_cuda_stream();
+
+  auto dst_type = output_q.scalar_type();
+
+  const bool is_column_major = output_s.stride(-2) < output_s.stride(-1);
+  STD_TORCH_CHECK(!scale_ue8m0 || round_scale,
+                  "packed UE8M0 scales require rounding");
+  STD_TORCH_CHECK(!round_scale || is_column_major,
+                  "rounded FP32 scales require column-major output");
+  const int hidden_dim_num_groups =
+      static_cast<int>(output_q.size(-1)) / group_size;
+  const int num_tokens_per_expert = static_cast<int>(output_q.size(-2));
+  const int scale_expert_stride =
+      masked_layout ? static_cast<int>(output_s.stride(0)) : 0;
+  const int scale_hidden_stride = static_cast<int>(output_s.stride(-1));
+
+#define LAUNCH_KERNEL_INNER(SCHEDULER, GROUP_SIZE, THREADS_PER_SUBWARP, T,   \
+                            DST_DTYPE, output_s_dtype, ...)                  \
+  do {                                                                       \
+    int subwarps_per_block;                                                  \
+    dim3 grid, block;                                                        \
+    SCHEDULER::compute_exec_config(                                          \
+        THREADS_PER_SUBWARP, num_local_experts, hidden_dim_num_groups,       \
+        num_groups, num_tokens_per_expert, subwarps_per_block, grid, block); \
+                                                                             \
+    cudaLaunchConfig_t config;                                               \
+    config.gridDim = grid;                                                   \
+    config.blockDim = block;                                                 \
+    config.dynamicSmemBytes = 0;                                             \
+    config.stream = stream;                                                  \
+    cudaLaunchAttribute attrs[1];                                            \
+    attrs[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;        \
+    attrs[0].val.programmaticStreamSerializationAllowed =                    \
+        get_env_enable_pdl();                                                \
+    config.numAttrs = 1;                                                     \
+    config.attrs = attrs;                                                    \
+    cudaLaunchKernelEx(                                                      \
+        &config,                                                             \
+        per_token_group_quant_8bit_kernel<SCHEDULER, GROUP_SIZE,             \
+                                          THREADS_PER_SUBWARP, T, DST_DTYPE, \
+                                          __VA_ARGS__>,                      \
+        static_cast<const T*>(input.const_data_ptr()),                       \
+        static_cast<DST_DTYPE*>(output_q.mutable_data_ptr()),                \
+        static_cast<output_s_dtype*>(output_s.mutable_data_ptr()),           \
+        static_cast<const int32_t*>(                                         \
+            masked_m.has_value() ? masked_m->const_data_ptr() : nullptr),    \
+        subwarps_per_block, hidden_dim_num_groups, scale_expert_stride,      \
+        scale_hidden_stride, num_tokens_per_expert,                          \
+        static_cast<float>(max_8bit), static_cast<float>(clamp_limit));      \
+  } while (0)
+
+#define LAUNCH_KERNEL(GROUP_SIZE, T, DST_DTYPE)                                \
+  do {                                                                         \
+    constexpr int THREADS_PER_SUBWARP = GROUP_SIZE / 16;                       \
+    STD_TORCH_CHECK(THREADS_PER_SUBWARP * INPUT_PRIMARY_VEC_NUM_BYTES ==       \
+                    group_size * sizeof(T));                                   \
+                                                                               \
+    using dst_dtype_info = DtypeInfo<DST_DTYPE>;                               \
+    CHECK_EQ(dst_dtype_info::MIN, min_8bit);                                   \
+    CHECK_EQ(dst_dtype_info::MAX, max_8bit);                                   \
+                                                                               \
+    if (is_column_major) {                                                     \
+      if (scale_ue8m0) {                                                       \
+        if (fuse_silu_and_mul) {                                               \
+          if (masked_layout) {                                                 \
+            LAUNCH_KERNEL_INNER(MaskedLayoutScheduler, GROUP_SIZE,             \
+                                THREADS_PER_SUBWARP, T, DST_DTYPE, uint32_t,   \
+                                true, true, true);                             \
